<script setup lang="ts">
import { PhArrowLeft, PhCheckCircle, PhIdentificationCard, PhPackage, PhPhone, PhWarning } from '@phosphor-icons/vue'
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import AdminLayout from '@/layouts/AdminLayout.vue'
import StatePanel from '@/components/StatePanel.vue'
import ConfirmDialog from '@/components/ConfirmDialog.vue'
import type { BookingStatus, GuaranteeStatus, PaymentStatus } from '@/domain/models'
import { applyAdminTransition, getAdminBookingDetail, type AdminBookingDetailView, type AdminTransition } from '@/services/admin'
import { canTransitionBooking, canTransitionGuarantee, canTransitionPayment } from '@/services/transitions'
import { useDemoStore } from '@/stores/demo'
import { formatIdr } from '@/utils/currency'
import { formatWita } from '@/utils/datetime'
import { statusLabel } from '@/utils/status'

const route = useRoute(); const demo = useDemoStore(); const detail = ref<AdminBookingDetailView>(); const message = ref(''); const pendingAction = ref<AdminTransition>()
const bookingTargets: BookingStatus[] = ['confirmed', 'expired', 'cancelled', 'rejected', 'picked_up', 'returned', 'completed']
const paymentTargets: PaymentStatus[] = ['pending_verification', 'deposit_paid', 'paid_in_full', 'failed', 'expired', 'refunded']
const guaranteeTargets: GuaranteeStatus[] = ['presented', 'accepted', 'returned']
const bookingActions = computed(() => detail.value ? bookingTargets.filter(next => canTransitionBooking(detail.value!.booking, next)) : [])
const paymentActions = computed(() => detail.value ? paymentTargets.filter(next => canTransitionPayment(detail.value!.booking.paymentStatus, next)) : [])
const guaranteeActions = computed(() => detail.value ? guaranteeTargets.filter(next => canTransitionGuarantee(detail.value!.booking.guaranteeStatus, next)) : [])
function reload() { detail.value = getAdminBookingDetail(String(route.params.bookingId)) }
function applyTransition(action: AdminTransition) { const result = applyAdminTransition(String(route.params.bookingId), action); message.value = result.ok ? `Status ${action.kind} diperbarui.` : result.message; reload() }
function transition(action: AdminTransition) { if (action.kind === 'booking') pendingAction.value = action; else applyTransition(action) }
function confirmTransition() { if (pendingAction.value) applyTransition(pendingAction.value); pendingAction.value = undefined }
onMounted(() => { demo.hydrate(); reload() })
</script>

<template><AdminLayout><div class="mx-auto max-w-6xl px-4 py-8 sm:px-6 lg:px-8 lg:py-10"><StatePanel v-if="!detail" state="not-found" title="Booking tidak ditemukan" message="Referensi ini tidak ada dalam data demo." /><template v-else><RouterLink class="inline-flex items-center gap-2 text-sm font-black" to="/admin/bookings"><PhArrowLeft /> Daftar booking</RouterLink><div class="mt-6 flex flex-wrap items-start justify-between gap-4"><div><p class="text-sm font-extrabold text-muted">{{ detail.booking.reference }}</p><h1 class="mt-1 text-3xl font-black">{{ detail.booking.customerSnapshot.name }}</h1><p class="mt-2 text-sm text-muted">{{ formatWita(detail.booking.period.pickupAt) }} hingga {{ formatWita(detail.booking.period.returnAt) }}</p></div><div class="flex flex-wrap gap-2"><span class="status-badge status-limited">{{ statusLabel(detail.booking.status) }}</span><span class="status-badge status-available">{{ statusLabel(detail.booking.paymentStatus) }}</span><span class="status-badge status-limited">Jaminan: {{ statusLabel(detail.booking.guaranteeStatus) }}</span></div></div><p v-if="message" class="mt-5 rounded-xl border border-sand bg-white p-4 text-sm font-bold" role="status">{{ message }}</p>
<div class="mt-8 grid gap-6 lg:grid-cols-[minmax(0,1fr)_22rem]"><div class="grid gap-6"><section class="rounded-2xl border border-sand bg-white p-5"><h2 class="flex items-center gap-2 text-xl font-black"><PhPackage /> Item rental</h2><div class="mt-4 divide-y divide-sand"><div v-for="line in detail.booking.lines" :key="line.id" class="flex justify-between gap-4 py-3"><div><strong>{{ line.nameSnapshot }}</strong><p class="mt-1 text-xs text-muted">{{ line.quantity }} × {{ formatIdr(line.unitPriceSnapshot) }}</p></div><span class="text-xs font-bold uppercase text-muted">{{ line.kind }}</span></div></div><div v-if="detail.packageComponents.length" class="mt-4 rounded-xl bg-surface p-4"><p class="text-xs font-black uppercase tracking-wider text-muted">Komponen paket</p><p v-for="component in detail.packageComponents" :key="`${component.lineId}-${component.productName}`" class="mt-2 text-sm">{{ component.quantity }} × {{ component.productName }}</p></div></section><section class="rounded-2xl border border-sand bg-white p-5"><h2 class="text-xl font-black">Unit dialokasikan</h2><div class="mt-4 grid gap-3 sm:grid-cols-2"><div v-for="allocation in detail.allocations" :key="allocation.id" class="rounded-xl bg-surface p-4"><strong>{{ allocation.unitLabel }}</strong><p class="mt-1 text-xs text-muted">{{ allocation.productName }}</p></div></div></section><section class="rounded-2xl border border-sand bg-white p-5"><h2 class="text-xl font-black">Timeline</h2><ol class="mt-4 border-l border-sand pl-5"><li v-for="event in detail.booking.timeline" :key="event.id" class="relative pb-5 last:pb-0"><span class="absolute -left-[1.55rem] top-1 size-2 rounded-full bg-ink" /><strong class="text-sm">{{ event.label }}</strong><p class="mt-1 text-xs text-muted">{{ formatWita(event.at) }} · {{ event.actor }}</p></li></ol></section></div>
<aside class="grid content-start gap-5"><section class="rounded-2xl border border-sand bg-white p-5"><h2 class="flex items-center gap-2 font-black"><PhPhone /> Kontak pelanggan</h2><p class="mt-4 font-bold">{{ detail.booking.customerSnapshot.name }}</p><p class="mt-2 text-sm">{{ detail.booking.customerSnapshot.whatsapp }}</p><p v-if="detail.booking.customerSnapshot.email" class="mt-1 break-all text-sm text-muted">{{ detail.booking.customerSnapshot.email }}</p></section><section class="rounded-2xl border border-sand bg-white p-5"><h2 class="font-black">Ringkasan biaya</h2><dl class="mt-4 grid gap-3 text-sm"><div class="flex justify-between"><dt>Subtotal</dt><dd class="font-black">{{ formatIdr(detail.booking.pricing.rentalSubtotal) }}</dd></div><div class="flex justify-between"><dt>DP tercatat</dt><dd>{{ formatIdr(detail.booking.pricing.depositPaid) }}</dd></div><div class="flex justify-between border-t border-sand pt-3"><dt>Sisa</dt><dd class="font-black">{{ formatIdr(detail.booking.pricing.remainingBalance) }}</dd></div></dl></section><section class="rounded-2xl border border-sand bg-white p-5"><h2 class="flex items-center gap-2 font-black"><PhCheckCircle /> Aksi simulasi</h2><div class="mt-5"><p class="text-xs font-black text-muted">STATUS BOOKING</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="next in bookingActions" :key="next" class="button-outline inline-flex" type="button" @click="transition({ kind: 'booking', next })">{{ statusLabel(next) }}</button><span v-if="!bookingActions.length" class="text-xs text-muted">Tidak ada transisi lanjutan.</span></div><p v-if="detail.booking.status === 'confirmed' && detail.booking.guaranteeStatus !== 'accepted'" class="mt-3 text-xs leading-5 text-warning">Status Sedang disewa baru tersedia setelah jaminan fisik dicatat sebagai Diterima.</p></div><div class="mt-5"><p class="text-xs font-black text-muted">PEMBAYARAN</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="next in paymentActions" :key="next" class="button-outline inline-flex" type="button" @click="transition({ kind: 'payment', next })">{{ statusLabel(next) }}</button><span v-if="!paymentActions.length" class="text-xs text-muted">Tidak ada transisi lanjutan.</span></div></div><div class="mt-5"><p class="flex items-center gap-2 text-xs font-black text-muted"><PhIdentificationCard /> JAMINAN FISIK</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="next in guaranteeActions" :key="next" class="button-outline inline-flex" type="button" @click="transition({ kind: 'guarantee', next })">{{ statusLabel(next) }}</button><span v-if="!guaranteeActions.length" class="text-xs text-muted">Tidak ada transisi lanjutan.</span></div><p class="mt-3 flex gap-2 text-xs leading-5 text-muted"><PhWarning class="mt-0.5 shrink-0" />Hanya status dicatat. Nomor, foto, atau isi dokumen tidak disimpan.</p></div></section></aside></div><ConfirmDialog :open="Boolean(pendingAction)" title="Konfirmasi perubahan status" :message="`Status booking akan diubah menjadi ${pendingAction ? statusLabel(pendingAction.next) : ''}. Perubahan ini hanya berlaku pada data demo lokal.`" confirm-label="Ubah status" @confirm="confirmTransition" @cancel="pendingAction = undefined" /></template></div></AdminLayout></template>
